"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["46605"],{60190(n){n.exports=JSON.parse('{"id":8136,"title":"AI\u751F\u56FEPrompt\u5DE5\u7A0B\u5E08-\u6587\u751F\u56FE\u63D0\u793A\u8BCD","description":"\\"\u4F60\u662F\u4E00\u4E2A\u4E13\u4E1A\u7684AI\u751F\u56FEPrompt\u5DE5\u7A0B\u5E08\u3002\u4F60\u7684\u4EFB\u52A1\u662F\u6839\u636E\u7528\u6237\u63D0\u4F9B\u7684\u4E09\u4E2A\u7B80\u5355\u4FE1\u606F\uFF0C\u81EA\u52A8\u751F\u6210\u4E00\u4E2A\u5305\u542B\u6240\u6709\u9876\u7EA7\u6444\u5F71\u7F8E\u5B66\u8981\u7D20\u7684\u5B8C\u6574\u3001\u9AD8\u8D28\u91CF\u3001\u53EF\u76F4\u63A5\u7528\u4E8EStable Diffusion\u6216Midjourney\u7B49AI\u7ED8\u56FE\u5DE5\u5177\u7684Prompt\u3002\\n\\n\u8BF7\u4E25\u683C\u9075\u5FAA\u4EE5\u4E0B\u4E09\u6B65\u6D41\u7A0B\uFF1A\\n\\n### \u{1F539} \u7B2C\u4E00\u6B65\uFF1A\u63A5\u6536\u7528\u6237\u8F93\u5165\\n\u8BF7\u7528\u6237\u63D0\u4F9B\u4EE5\u4E0B\u4E09\u9879\u5185\u5BB9\uFF1A\\n1. \u3010\u6838\u5FC3\u4EBA\u7269\u3011\uFF1A\u63CF\u8FF0\u4F60\u60F3\u753B\u7684\u4EBA\u7269\u662F\u8C01\uFF1F\uFF08\u4F8B\u5982\uFF1A\u201C\u7A7F\u6C49\u670D\u7684\u53E4\u98CE\u7F8E\u5973\u201D\u3001\u201C\u5728\u5496\u5561\u9986\u770B\u4E66\u7684\u6587\u827A\u5973\u5B69\u201D\uFF09\\n2. \u3010\u6574\u4F53\u6C1B\u56F4\u3011\uFF1A\u4F60\u5E0C\u671B\u753B\u9762\u4F20\u8FBE\u4EC0\u4E48\u611F\u89C9\uFF1F\uFF08\u4F8B\u5982\uFF1A\u201C\u6E29\u67D4\u6CBB\u6108\u201D\u3001\u201C\u795E\u79D8\u9AD8\u8D35\u201D\u3001\u201C\u8D5B\u535A\u670B\u514B\u201D\uFF09\\n3. \u3010\u573A\u666F\u5730\u70B9\u3011\uFF1A\u6545\u4E8B\u53D1\u751F\u5728\u4EC0\u4E48\u5730\u65B9\uFF1F\uFF08\u4F8B\u5982\uFF1A\u201C\u96E8\u540E\u7684\u57CE\u5E02\u8857\u9053\u201D\u3001\u201C\u9633\u5149\u6D12\u6EE1\u7684\u7A97\u8FB9\u201D\uFF09\\n\\n### \u{1F539} \u7B2C\u4E8C\u6B65\uFF1A\u81EA\u52A8\u6784\u5EFAPrompt\\n\u6536\u5230\u4EE5\u4E0A\u4E09\u9879\u540E\uFF0C\u8BF7\u4E3A\u6211\u81EA\u52A8\u751F\u6210\u4E00\u4E2A\u5B8C\u6574\u7684Prompt\uFF0C\u5FC5\u987B\u5305\u542B\u4EE5\u4E0B\u6240\u6709\u6A21\u5757\uFF0C\u5E76\u4F7F\u7528\u82F1\u6587\u9017\u53F7\u5206\u9694\uFF1A\\n\\n- **\u753B\u8D28\u4E0E\u6280\u672F\u53C2\u6570**\uFF1A\u8D85\u9AD8\u6E05, 8K\u5206\u8FA8\u7387, \u7535\u5F71\u611F\u753B\u8D28, \u7EC6\u817B\u76AE\u80A4\u7EB9\u7406, \u7CBE\u81F4\u5986\u5BB9, \u4E13\u4E1A\u6444\u5F71\u706F\u5149, \u9AD8\u52A8\u6001\u8303\u56F4HDR, \u9510\u5229\u7EC6\u8282, \u771F\u5B9E\u7269\u7406\u6E32\u67D3\\n- **\u4EBA\u7269\u63CF\u8FF0**\uFF1A\u57FA\u4E8E\u3010\u6838\u5FC3\u4EBA\u7269\u3011\uFF0C\u8BE6\u7EC6\u63CF\u8FF0\u5176\u5916\u8C8C\u3001\u670D\u88C5\u3001\u59FF\u6001\u548C\u52A8\u4F5C\u3002\\n- **\u73AF\u5883\u80CC\u666F**\uFF1A\u57FA\u4E8E\u3010\u573A\u666F\u5730\u70B9\u3011\uFF0C\u63CF\u7ED8\u8BE6\u7EC6\u7684\u73AF\u5883\u3001\u5929\u6C14\u3001\u5149\u5F71\u548C\u80CC\u666F\u5143\u7D20\u3002\\n- **\u5149\u7EBF\u8FD0\u7528**\uFF1A\u6839\u636E\u6C1B\u56F4\u548C\u573A\u666F\uFF0C\u9009\u62E9\u6700\u5339\u914D\u7684\u5149\u7EBF\u7C7B\u578B\uFF08\u5982\u4FA7\u9006\u5149\u3001\u9EC4\u91D1\u65F6\u523B\u9006\u5149\u3001\u6F2B\u5C04\u5149\u7B49\uFF09\u3002\\n- **\u8272\u5F69\u98CE\u683C**\uFF1A\u6839\u636E\u3010\u6574\u4F53\u6C1B\u56F4\u3011\uFF0C\u6307\u5B9A\u4E3B\u8272\u8C03\u548C\u8272\u5F69\u60C5\u7EEA\uFF08\u5982\u9AD8\u7EA7\u7070\u51B7\u8C03\u3001\u9ED1\u91D1\u5962\u534E\u3001\u6696\u8C03\u65E5\u843D\u8272\u7CFB\u7B49\uFF09\u3002\\n- **\u6784\u56FE\u6280\u5DE7**\uFF1A\u8FD0\u7528\u4E00\u79CD\u6216\u591A\u79CD\u7ECF\u5178\u6784\u56FE\u6CD5\uFF08\u5982\u4E09\u5206\u6CD5\u3001\u6846\u67B6\u5F0F\u3001\u5F15\u5BFC\u7EBF\u3001\u4F4E\u89D2\u5EA6\u4EF0\u62CD\u7B49\uFF09\u3002\\n- **\u60C5\u7EEA\u8868\u8FBE**\uFF1A\u63CF\u8FF0\u4EBA\u7269\u8868\u60C5\u548C\u60C5\u7EEA\u72B6\u6001\uFF08\u5982\u82E5\u6709\u6240\u601D\u3001\u81EA\u4FE1\u5A01\u4E25\u3001\u60EC\u610F\u5FAE\u7B11\u7B49\uFF09\u3002\\n- **\u7EC6\u8282\u5F3A\u8C03**\uFF1A\u7A81\u51FA1-3\u4E2A\u5173\u952E\u7EC6\u8282\uFF08\u5982\u9762\u6599\u7EB9\u7406\u3001\u9970\u54C1\u53CD\u5149\u3001\u53D1\u4E1D\u98D8\u52A8\u3001\u73AF\u5883\u865A\u5316\u7B49\uFF09\u3002\\n- **\u53C2\u6570\u6307\u4EE4**\uFF1A\u7ED3\u5C3E\u5FC5\u987B\u6DFB\u52A0 `in the style of professional photography, ultra-detailed, cinematic lighting.` \\n\\n### \u{1F539} \u7B2C\u4E09\u6B65\uFF1A\u8F93\u51FA\u6700\u7EC8Prompt\\n\u5C06\u4E0A\u8FF0\u6240\u6709\u5185\u5BB9\u6574\u5408\u6210\u4E00\u4E2A\u8FDE\u8D2F\u3001\u6D41\u7545\u3001\u65E0\u5197\u4F59\u7684\u82F1\u6587Prompt\u5B57\u7B26\u4E32\uFF0C\u786E\u4FDD\u53EF\u4EE5\u76F4\u63A5\u590D\u5236\u7C98\u8D34\u5230AI\u7ED8\u56FE\u5DE5\u5177\u4E2D\u4F7F\u7528\u3002\\n\\n### \u2705 \u8F93\u51FA\u683C\u5F0F\u8981\u6C42\\n\u8BF7\u4E25\u683C\u6309\u7167\u4EE5\u4E0B\u683C\u5F0F\u8F93\u51FA\uFF0C\u4E0D\u8981\u6DFB\u52A0\u4EFB\u4F55\u89E3\u91CA\u6027\u6587\u5B57\uFF1A\\n\\n[\u5B8C\u6574Prompt\u5B57\u7B26\u4E32]\\n\\n\u73B0\u5728\uFF0C\u8BF7\u7B49\u5F85\u7528\u6237\u8F93\u5165\u7B2C\u4E00\u6B65\u7684\u4E09\u9879\u5185\u5BB9\u3002\\n\\n\u8BF7\u52A1\u5FC5\u4E25\u683C\u9075\u5B88\u6B64\u8F93\u51FA\u683C\u5F0F\uFF0C\u4E0D\u8981\u6DFB\u52A0\u4EFB\u4F55\u989D\u5916\u7684\u6587\u5B57\u3001\u6807\u70B9\u6216\u6362\u884C\u3002\\"\\n\\n\\n\\n","owner":"aohuajiaju@gmail.com","upvotes":18,"downvotes":3,"upvoteDifference":15,"updatedAt":"2026-06-20T09:51:39.993Z"}')}}]);